#include <iostream>
#include <string>

class ResourceHolder {
private:
    std::string* data;  // Example resource: a dynamically allocated string

public:
    // Constructor that allocates the resource
    ResourceHolder() : data(new std::string) {}

    // Destructor to free the resource
    ~ResourceHolder() {
        delete data;  // Releases the allocated memory
    }

    // Copy constructor for deep copying
    ResourceHolder(const ResourceHolder& other) : data(new std::string(*other.data)) {}

    // Copy-assignment operator for deep copying
    ResourceHolder& operator=(const ResourceHolder& other) {
        if (this != &other) {  // Check for self-assignment
            delete data;  // Free existing resource
            data = new std::string(*other.data);  // Deep copy the resource
        }
        return *this;
    }

    // Accessor for demonstration
    const std::string& getData() const { return *data; }
};

int main() {
    ResourceHolder obj1;
    *obj1.data = "Hello, World!";  // Use the resource

    ResourceHolder obj2 = obj1;  // Invokes copy constructor
    std::cout << "obj2 data: " << obj2.getData() << std::endl;  // Outputs: Hello, World!

    ResourceHolder obj3;
    obj3 = obj1;  // Invokes copy-assignment operator
    std::cout << "obj3 data: " << obj3.getData() << std::endl;  // Outputs: Hello, World!

    return 0;
}
